// Program.cs - A minimal C# console application
// Top-level statements: no class or Main method needed!

Console.WriteLine("Hello, World!");

using System;

namespace MyFirstApp
{
    class Program
    {
        // The entry point of the application
        static void Main(string[] args)
        {
            Console.WriteLine("Hello, World!");

            // Variables
            string name = "Alice";
            int age = 25;

            Console.WriteLine($"Name: {name}, Age: {age}");

            // Reading input from the user
            Console.Write("Enter your name: ");
            string? userInput = Console.ReadLine();

            if (!string.IsNullOrEmpty(userInput))
            {
                Console.WriteLine($"Welcome, {userInput}!");
            }
        }
    }
}

string name = "Alice";
int age = 25;
double price = 19.99m;

// String interpolation with $
Console.WriteLine($"Hello, {name}!");
Console.WriteLine($"You are {age} years old.");
Console.WriteLine($"The price is ${price:F2}");

// Expressions inside interpolation
Console.WriteLine($"Next year you'll be {age + 1}");
Console.WriteLine($"{name} is {(age >= 18 ? "an adult" : "a minor")}");

// String concatenation (older style, less readable)
Console.WriteLine("Hello, " + name + "! You are " + age + " years old.");

// Composite formatting (older style)
Console.WriteLine("Hello, {0}! You are {1} years old.", name, age);

Console.Write("Enter your age: ");
string? ageInput = Console.ReadLine();

// Convert string to int
if (int.TryParse(ageInput, out int age))
{
    Console.WriteLine($"You are {age} years old.");
    int nextYear = age + 1;
    Console.WriteLine($"Next year you'll be {nextYear}");
}
else
{
    Console.WriteLine("That's not a valid number!");
}

// Convert to double for decimal values
Console.Write("Enter price: ");
string? priceInput = Console.ReadLine();
if (decimal.TryParse(priceInput, out decimal price))
{
    Console.WriteLine($"Price with tax: {price * 1.1m:C}");
}

// Using newer target-typed new (C# 12)
int count = int.Parse(Console.ReadLine() ?? "0");

Console.Write("Success: ");
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("Operation completed!");
Console.ResetColor();

Console.Write("Error: ");
Console.ForegroundColor = ConsoleColor.Red;
Console.WriteLine("Something went wrong!");
Console.ResetColor();

/// <summary>
/// Greets a person by name.
/// </summary>
/// <param name="name">The name of the person to greet.</param>
/// <returns>A greeting string.</returns>
public string Greet(string name)
{
    return $"Hello, {name}!";
}
